  var $ = function (s, r) { return (r || document).querySelector(s) };
  var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c] }) };
  var rota = (location.hash || '#inicio').slice(1), menuAberto = false, rasc = null, msg = '', draftFb = null, pref = false, detalhes = false;
  var sel = {}, filtro = '', maisAberto = false, dlgCanal = false, dlgDisp = false, draftDisp = null, termos = false, abertos = {};
  function s() { return SITE.get() }
  function grava(f) { var st = s(); f(st); SITE.set(st) }
