      P.map(function (p) { var pr = p.arq ? T('Arquivado: não sincroniza', 'Archivado: no se sincroniza') : (!p.cat ? T('Falta a categoria do produto', 'Falta la categoría del producto') : (!p.img ? T('Falta uma imagem', 'Falta una imagen') : '—'));
        return '<tr data-t="fbp-' + p.id + '"><td>' + esc(p.nome) + '</td><td><select data-catp="' + p.id + '" data-t="sel-cat-' + p.id + '"><option value="" data-pt="">' + T('Escolha uma categoria de produto', 'Elige una categoría de producto') + '</option>' + cats.map(function (c) { return '<option value="' + esc(c) + '" data-pt="' + esc(c) + '"' + (p.cat === c ? ' selected' : '') + '>' + esc(c) + '</option>' }).join('') + '</select></td><td data-t="fbp-prob-' + p.id + '">' + pr + '</td></tr>' }).join('') + '</table>' +
      '<button class="sh-bt prim" data-ac="salvar-fbp" data-t="btn-salvar-fbp">' + T('Salvar', 'Guardar') + '</button> <span class="sh-ok" data-t="fbp-status">' + esc(msg) + '</span></div><p class="sh-nota">' + T('Os produtos sincronizados devem ser editados na Shopify (a Categoria fica na página do produto): a mudança chega à Meta na próxima sincronização, em poucos minutos. ⚠ Esta lista de problemas do canal: a conferir com a tela real.', 'Los productos sincronizados deben editarse en Shopify (la Categoría está en la página del producto): el cambio llega a Meta en la próxima sincronización, en pocos minutos. ⚠ Esta lista de problemas del canal: por confirmar con la pantalla real.') + '</p>';
